"""Build a private review gallery from real before/after CAD snapshots."""
import html,json
from pathlib import Path
from catalog import CASES
REPO=Path(__file__).resolve().parents[2];OUT=REPO/'outputs/50-model-audit'
css='''*{box-sizing:border-box}body{margin:0;background:#f2f3f5;color:#26333f;font:14px system-ui}header{padding:24px 32px;background:white;border-bottom:1px solid #cbd3dc;position:sticky;top:0;z-index:2}h1{margin:0 0 8px;font-size:25px}.muted{color:#5d6d7c;font-size:12px}main{padding:22px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.card{background:white;border:1px solid #cbd3dc;border-radius:8px;overflow:hidden}.card h2{font-size:15px;margin:14px 16px 4px}.category{margin:0 16px 10px;color:#607285;font-size:11px}.images{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:#e2e6eb}.images figure{margin:0;background:#f1f2f4}.images img{width:100%;aspect-ratio:1.42;object-fit:contain;display:block}.images figcaption{text-align:center;padding:5px;background:#e8eef4;font-size:10px}.details{padding:10px 16px;font-size:11px;line-height:1.5}.details p{margin:5px 0}a{color:#135d98}.tag{display:inline-block;padding:3px 7px;background:#dcefe4;color:#246442;border-radius:4px;font-size:11px;margin-right:8px}input{padding:9px;width:310px;border:1px solid #aebdcc;border-radius:5px}nav a{margin-right:16px}button{padding:8px;cursor:pointer}@media(max-width:800px){main{grid-template-columns:1fr}header{position:relative;padding:18px}input{width:100%}}'''
def card(i,c):
 folder=OUT/c['key'];native=json.loads((folder/'native.json').read_text());ai=json.loads((folder/'ai.json').read_text());release_path=folder/'release.json';release=json.loads(release_path.read_text()) if release_path.exists() else {};picture=c['key']+('/release/viewer.png' if (folder/'release/viewer.png').exists() else '/ai.png');url=release.get('viewer_url',ai.get('viewer_url',native['viewer_url']))
 return f'''<article class="card" data-search="{html.escape((c['name']+' '+c['category']).lower())}"><h2>{i:02d} · {html.escape(c['name'])}</h2><p class="category">{html.escape(c['category'])}</p><div class="images"><figure><img src="{c['key']}/native.png" alt="Before edit"><figcaption>Baseline CAD · actual viewer</figcaption></figure><figure><img src="{picture}" alt="After live AI edit"><figcaption>Live AI edit · actual viewer</figcaption></figure></div><div class="details"><span class="tag">CAD {native['status']}</span><span class="tag">Live AI {ai['status']}</span><p>{html.escape(c['edit'])}</p><a href="{html.escape(url)}" target="_blank">Open interactive model</a> · <a href="{c['key']}/release/model.step">STEP</a> · <a href="{c['key']}/release/model.stl">STL</a> · <a href="{c['key']}/release/program.py">Editable Python</a></div></article>'''
script="""document.querySelector('#filter').addEventListener('input',e=>{for(const card of document.querySelectorAll('.card'))card.hidden=!card.dataset.search.includes(e.target.value.toLowerCase());});"""
for group in range(6):
 items=list(enumerate(CASES,1)) if group==0 else list(enumerate(CASES,1))[(group-1)*10:group*10]
 title='50-model Intact audit' if group==0 else f'Visual review {group} · models {items[0][0]}–{items[-1][0]}'
 page='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>'+css+'</style><header><h1>'+title+'</h1><p class="muted">Real CAD and live AI edits. Geometry, native topology, exports and image snapshots were verified. Each view is fitted independently; dimensions are compared in native CAD. This gallery is local/private.</p><nav><a href="gallery.html">All 50</a>'+''.join(f'<a href="review-{n}.html">{n*10-9}–{n*10}</a>' for n in range(1,6))+'</nav><p><input id="filter" placeholder="Filter model or operation"></p></header><main>'+''.join(card(i,c) for i,c in items)+'</main><script>'+script+'</script></html>'
 (OUT/('gallery.html' if group==0 else f'review-{group}.html')).write_text(page)
print('Created private gallery of 50 before/after CAD pairs')
